contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params let checker vary inputs
    function run(address whaleAddr, uint256 initialBetLimit, uint256 playDelayBlock, uint256 sendAmount) public payable {
        // Preconditions for meaningful scenario:
        // - initialBetLimit must be > 0 so wager requires a positive value
        // - sendAmount must equal initialBetLimit to successfully call wager
        require(initialBetLimit > 0);
        require(sendAmount == initialBetLimit);

        // Deploy-time constructor of c was already executed by harness; we only interact.
        // Set up: owner-only calls must be done by c's owner; our test contract is not owner.
        // To allow wagering we need c to be open to public. The onlyOwner modifier prevents us from calling OpenToThePublic.
        // However, the harness deploys c; we cannot assume owner. To create a valid observable property we instead
        // assume that OpenToThePublic has been called by the owner before this run, or that openToPublic is true.
        // We therefore check publicly-observable flag and require it to be true to proceed.
        require(c.currentBetLimit() == initialBetLimit);
        // require openToPublic by inferring ability to call wager: best we can do is try and detect revert.

        // Ensure the contract has at least enough balance so payout (which pays half balance) can happen meaningfully.
        // Fund c by sending some Ether directly from this contract to c if we have balance.
        if (address(this).balance >= sendAmount) {
            // send sendAmount to c to seed its balance (this is a plain transfer to fallback)
            (bool ok,) = address(c).call{value: sendAmount}("");
            // ignore success; main checks below will account for behaviors
        }

        // Attempt to wager: must send exactly betLimit. Use try/catch to record revert.
        bool wagerReverted;
        try c.wager{value: sendAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Record whether hasPlayerWagered (observable). Note: msg.sender inside c is this contract.
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // If wager reverted, then hasWagerAfter must be false.
        if (wagerReverted) {
            assert(hasWagerAfter == false);
            return;
        }

        // If wager succeeded, now simulate waiting at least one block by relying on the checker to advance block.number between calls.
        // Try calling play and capture whether it reverts. play requires block.number > timestamps[msg.sender].
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // After a successful play call (no revert), the player must no longer have an active wager.
        // This is the general invariant we assert: whenever play returns (does not revert), hasPlayerWagered(address(this)) == false
        // We also allow the case where play reverted; then we make no assertion about wagers (but still must reach an assert).
        assert(playReverted || c.hasPlayerWagered(address(this)) == false);
    }

    // allow receiving Ether so this contract can fund c
    receive() external payable {}
}

