contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single scenario: open the contract, then wager with some amount equal to current bet limit
    // params: whale address and wagerLimit are used at C's construction (handled by deployer), so here
    // we take amount to send and caller is this contract (the test contract) interacting with c.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Ensure contract is open to public by calling OpenToThePublic from the owner (the test deployed C, so this contract is owner)
        // This call changes c's state; do it top-level.
        c.OpenToThePublic();

        // Read current bet limit
        uint256 limitBefore = c.currentBetLimit();
        uint256 balanceBefore = address(c).balance;

        // Only attempt wager when amount equals the reported bet limit. We allow the property prover to pick amount accordingly.
        bool reverted;
        // make the call that changes state: wager() payable
        // We expect it to revert if amount != limitBefore or if other preconditions fail, otherwise succeed.
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        bool hasWager = c.hasPlayerWagered(address(this));

        // General rule: if we sent exactly the bet limit and the call did not revert,
        // then hasPlayerWagered must be true and contract balance must have increased by amount.
        assert( !reverted && amount == limitBefore ? (hasWager && balanceAfter == balanceBefore + amount) : true );
    }

    receive() external payable { }
}

