        c.AdjustBetAmounts(initialBetLimit);
        c.OpenToThePublic();

        // Ensure we send exactly the bet amount to create a player wager only when sendAmount == bet limit
        bool didWagerRevert;
        try c.wager{value: sendAmount}() {
            didWagerRevert = false;
        } catch {
            didWagerRevert = true;
        }

        // If wager reverted, we cannot become a player; in that case we skip play attempt.
        bool playReverted = true;
        bool beforeHad = c.hasPlayerWagered(address(this));
        uint256 beforeBal = address(c).balance;
        if (!didWagerRevert) {
            // only attempt play if we believe we are a player
            try c.play() {
                playReverted = false;
            } catch {
                playReverted = true;
            }
        }
        uint256 afterBal = address(c).balance;
        bool afterHad = c.hasPlayerWagered(address(this));

        // General rule:
        // If play did not revert then the player must no longer have a recorded wager (afterHad == false),
        // and the contract balance cannot have increased; it either stays the same or decreases by at most the bet limit.
        // If play reverted or was not attempted, we make no claim about changes.
        assert( playReverted || (afterHad == false && afterBal <= beforeBal && beforeBal - afterBal <= c.currentBetLimit()) );
    }
    receive() external payable {}
}

