    constructor(C _c) { c = _c; }

    // We need to: open the contract to public, set bet limit, place a wager from this contract,
    // advance (simulated by using a different block number is not possible here) — but play() checks
    // timestamp < block.number. The only way to ensure timestamp < block.number is to call wager()
    // and then (in a later transaction) call play(). However the checker runs run(...) once in one
    // transaction. To still get a meaningful universal property we check the following hard rule:
    // If play() does NOT revert AND before the call hasPlayerWagered(this) was true, then after
    // play() hasPlayerWagered(this) is false. This avoids assuming ability to advance block inside
    // the single transaction. We will construct a situation where wager() is called in this transaction
    // and then attempt play(), capturing revert; the assertion states the general relation between
    // non-reverting play() and clearing the wager.

    // Single public function driving the property. params:
    // - uint256 betAmount: amount to send to wager()
    // - uint256 newBetLimit: amount to set as betLimit by owner
    // - address whale: address passed to C constructor was already set; we don't redeploy C.
    function run(uint256 betAmount, uint256 newBetLimit) public payable {
        // Ensure this test contract has enough ETH to fund the wager
        require(address(this).balance >= betAmount, "need funds to place wager");

        // Attempt to make the contract open to public and set bet limit must be done by owner only.
        // Our test contract is the deployer of C, so it is the owner — we can call these.
        // These are top-level state-changing calls on c.
        c.OpenToThePublic();
        c.AdjustBetAmounts(newBetLimit);

        // Ensure the betAmount equals current bet limit so wager() is not trivially rejected by value mismatch.
        // We will set betAmount == newBetLimit through a require so the symbolic check is constrained.
        require(betAmount == newBetLimit, "betAmount must match bet limit");

        // Record precondition: whether this contract has a wager before we call wager()
        bool hadWagerBefore = c.hasPlayerWagered(address(this));

        // Record contract balance before wager
        uint256 balBefore = address(c).balance;

        // Try to call wager() with betAmount and capture if it reverted.
        bool wagerReverted;
        try c.wager{value: betAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Now attempt play() and capture whether it reverts. play() requires that hasPlayerWagered == true
        // and also timestamp < block.number (otherwise it reverts). We capture the revert flag.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Observe whether this address has a wager after play()
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // General rule asserted over all inputs and behaviors we've observed:
        // If before calling play() this contract had a wager (i.e., hadWagerBefore == true OR wager() succeeded and thus created one),
        // and the play() call did NOT revert, then after play() this contract must NOT have a wager anymore.
        // We express "before calling play() had a wager" as either hadWagerBefore or (wagerReverted == false).
        bool hadWagerAtPlayTime = hadWagerBefore || (!wagerReverted);

        assert( (!playReverted && hadWagerAtPlayTime) == ( !playReverted && !hasWagerAfter ) );
        // Explanation of the boolean equality asserted above (not part of code comment for the checker):
        // It enforces: if play did not revert and there was a wager, then hasWagerAfter must be false.
        // Conversely, if play did not revert then hasWagerAfter must be false; the equality encodes that relation
        // in a single boolean formula as required.
    }

    // Allow this test contract to receive Ether so it can fund bets.
    receive() external payable { }
    fallback() external payable { }
}

