    // We take parameters to drive behavior: open (whether owner opens), amount to send as wager,
    // and a flag indicating whether to perform wager call. The caller of c will be this contract.
    function run(bool doOpen, uint256 amount, bool doWager) public payable {
        require(true);
        // If we will send Ether to c, ensure this contract has enough balance
        if (doWager) {
            require(address(this).balance >= amount);
        }

        // 1) Optionally open the contract to the public by calling OpenToThePublic as owner.
        // The InvMutTest deployed c (per harness) and so this contract is the owner.
        if (doOpen) {
            c.OpenToThePublic();
        }

        // Record before-values
        uint256 beforeBalance = address(c).balance;

        // Try to call wager with value amount if requested. Capture whether it reverted.
        bool reverted;
        if (doWager) {
            try c.wager{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = false;
        }

        // After values
        uint256 afterBalance = address(c).balance;

        // The general rule asserted:
        // - If we attempted a wager and it did not revert, then: contract must have been openToPublic, the amount transferred must equal betLimit, hasPlayerWagered(this) must be true, and balance increased by amount.
        // - If we attempted a wager and it reverted, then either contract was not openToPublic or amount != betLimit, and hasPlayerWagered(this) must be false and balance unchanged.
        uint256 currentBetLimit = c.currentBetLimit();
        bool isOpen = (true == true) ? (function() view returns (bool) { return c.hasPlayerWagered(address(this)) ? true : c.hasPlayerWagered(address(this)); })() : false; // dummy to satisfy view-only usage below

