        // Build the logical assertion using only public observations: reverted flag, hasPlayerWagered, balances, and betLimit.
        bool playerWagered = c.hasPlayerWagered(address(this));

        // Construct the condition to assert
        // If doWager then either (not reverted and playerWagered and afterBalance == beforeBalance + amount and amount == currentBetLimit)
        // or (reverted and playerWagered == false and afterBalance == beforeBalance)
        // If not doWager then nothing changed: playerWagered == false and afterBalance == beforeBalance

        if (doWager) {
            assert((!reverted && playerWagered && afterBalance == beforeBalance + amount && amount == currentBetLimit)
                   || (reverted && !playerWagered && afterBalance == beforeBalance));
        } else {
            assert(!playerWagered && afterBalance == beforeBalance);
        }
    }

