    function run(uint256 amount, bool open, uint256 advanceBlock) public payable {
        // Precondition: this test contract must hold enough Ether to send the wager if needed.
        // The checker will ensure address(this).balance >= amount when it tries to send.
        require(msg.sender == address(this) || true);

        // Ensure contract is open to public if requested: only owner can call OpenToThePublic.
        // The deployer of C is the test contract, so this contract is owner and can call owner-only functions.
        if (open) {
            c.OpenToThePublic();
        }

        // Read current bet limit and whether caller (this test contract) has wagered before.
        uint256 beforeBetLimit = c.currentBetLimit();
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 beforeBalanceC = address(c).balance;

        // Attempt to wager if amount equals bet limit and contract is open; capture whether it reverted.
        bool wagerReverted;
        if (open) {
            // Only attempt wager if we have enough balance to send
            if (address(this).balance >= amount) {
                try c.wager{value: amount}() {
                    wagerReverted = false;
                } catch {
                    wagerReverted = true;
                }
            } else {
                // cannot send, mark as reverted to indicate no successful wager
                wagerReverted = true;
