        bool afterHas = c.hasPlayerWagered(address(this));
        uint256 afterBalanceC = address(c).balance;

        // Now attempt to call play. play only succeeds when player had a wager and block.number > timestamp
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read hasPlayerWagered after play and contract balance and winnersPot
        bool finalHas = c.hasPlayerWagered(address(this));
        uint256 finalBalanceC = address(c).balance;
        uint256 winnersPot = c.winnersPot();

        // General rule asserted:
        // 1) If a wager call succeeded (did not revert) then afterHas must be true and contract balance must have increased by exactly amount.
        // 2) play can only clear the player's wager (finalHas == false) when it did not revert; if play reverted then finalHas must equal afterHas.
        // 3) winnersPot is always equal to half of contract balance (observable invariant of contract: winnersPot == address(c).balance / 2)
        assert(
