contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We attempt to call wager with a provided amount. If the call succeeds, the contract
    // balance must increase by that amount and hasPlayerWagered(this) must be true.
    // Otherwise the call must have reverted.
    // Note: wager() requires the contract to be openToPublic and the sent value == betLimit.
    // To avoid automatic revert due to mismatched betLimit, we query currentBetLimit()
    // and send that exact amount. Also ensure this test contract has enough Ether.
    function run() public payable {
        // get the required bet amount from c's public getter
        uint256 required = c.currentBetLimit();

        // ensure we have enough Ether to send the exact betLimit
        require(address(this).balance >= required);

        uint256 balBefore = address(c).balance;

        bool reverted;
        // single top-level state-changing call: try to wager with the exact betLimit
        try c.wager{value: required}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;
        bool hasWager = c.hasPlayerWagered(address(this));

        // general property: either reverted, or balance increased by exactly required and player marked
        assert(reverted || (balAfter == balBefore + required && hasWager));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We need to provide parameters to drive flows: whale addr and wager amount are set in C's constructor externally.
    // Inputs: amount to send when calling wager (must equal current betLimit to succeed), and a dummy blockNumberAdvance flag simulated by performing a noop call to advance block (not actually possible here), so we rely on the requirement that timestamps[msg.sender] < block.number when play is called.
    // To influence behavior, we will: open to public, set up a wager by this contract sending 'stake', then call play and observe outcomes.
    function run(uint256 stake) public payable {
        require(true);
        // ensure test contract has enough balance to send stake
        require(address(this).balance >= stake);
        // Make contract open to public (onlyOwner). The test-deployer was the owner when C was constructed, but here msg.sender is this contract; owner is external. We cannot call onlyOwner functions unless this contract is owner. So we cannot rely on OpenToThePublic. Instead we assume c is already openToPublic or wager/play will revert. We'll attempt calls and record revert flags.
        bool wagerReverted;
        bool playReverted;
        // Call wager: must send exactly betLimit. We don't know betLimit; passing stake may revert.
        try c.wager{value: stake}() { wagerReverted = false; } catch { wagerReverted = true; }
        // Read observable state after wager attempt
        uint256 balAfterWager = address(c).balance;
        bool hasWagered = c.hasPlayerWagered(address(this));
        uint256 betLimit = c.currentBetLimit();
        uint256 winnersPot = c.winnersPot();
        // Now attempt play. play will revert if no wager or block number condition not met or not open to public.
        try c.play() { playReverted = false; } catch { playReverted = true; }
        uint256 balAfterPlay = address(c).balance;
        // If play did not revert and it executed, then either payout() was called transferring winnersPot to this contract (since winner==this) or loseWager transferred amount to whale. We assert the general invariant relating balances:
        // If play reverted then nothing required. If play succeeded then either balance decreased by at least betLimit/2 (lose case) or balance equals balAfterWager - winnersPot (payout case where winnersPot was sent away). We express that as: if !playReverted then (balAfterPlay <= balAfterWager - (betLimit/2) || balAfterPlay + winnersPot == balAfterWager).
        // But winnersPot is defined as address(c).balance/2 (before payout), however we read winnersPot before calling play. Use that value.
        assert(playReverted || (balAfterPlay + winnersPot == balAfterWager) || (betLimit > 0 && balAfterWager - balAfterPlay >= betLimit/2));
    }
    receive() external payable { }
}

